package main
import("crypto/sha256";"encoding/hex";"encoding/json";"fmt";"os";"path/filepath";"sort";"strings")
func snapshot(root string)(map[string]string,error){out:=map[string]string{};info,e:=os.Stat(root);if e!=nil||!info.IsDir(){return nil,fmt.Errorf("root must be a directory")};e=filepath.WalkDir(root,func(path string,d os.DirEntry,err error)error{if err!=nil{return err};if d.IsDir()||d.Type()&os.ModeSymlink!=0{return nil};info,e:=d.Info();if e!=nil{return e};if !info.Mode().IsRegular(){return nil};if info.Size()>4<<20{return fmt.Errorf("file exceeds 4 MiB: %s",path)};if len(out)>=10000{return fmt.Errorf("file limit exceeded")};b,e:=os.ReadFile(path);if e!=nil{return e};h:=sha256.Sum256(b);rel,e:=filepath.Rel(root,path);if e!=nil{return e};out[filepath.ToSlash(rel)]=hex.EncodeToString(h[:]);return nil});return out,e}
func diff(a,b map[string]string)[]string{out:=[]string{};for k,v:=range a{if value,ok:=b[k];!ok{out=append(out,"DELETED "+k)}else if v!=value{out=append(out,"CHANGED "+k)}};for k:=range b{if _,ok:=a[k];!ok{out=append(out,"ADDED "+k)}};sort.Strings(out);return out}
func run(args []string)error{if len(args)!=3{return fmt.Errorf("usage: drift baseline|check FOLDER MANIFEST (manifest must be outside folder)")};root,e:=filepath.Abs(args[1]);if e!=nil{return e};manifest,e:=filepath.Abs(args[2]);if e!=nil{return e};rel,_:=filepath.Rel(root,manifest);if rel=="."||(rel!=".."&&!strings.HasPrefix(rel,".."+string(os.PathSeparator))){return fmt.Errorf("manifest must be outside scanned folder")};current,e:=snapshot(root);if e!=nil{return e};switch args[0]{case "baseline":b,e:=json.MarshalIndent(current,"","  ");if e!=nil{return e};f,e:=os.OpenFile(manifest,os.O_WRONLY|os.O_CREATE|os.O_EXCL,0600);if e!=nil{return e};_,e=f.Write(b);closeErr:=f.Close();if e!=nil{return e};return closeErr;case "check":b,e:=os.ReadFile(manifest);if e!=nil{return e};var old map[string]string;if e=json.Unmarshal(b,&old);e!=nil{return e};changes:=diff(old,current);for _,line:=range changes{fmt.Println(line)};if len(changes)>0{return fmt.Errorf("drift detected: %d changes",len(changes))};fmt.Println("No content drift");return nil;default:return fmt.Errorf("unknown command")}}
func main(){if e:=run(os.Args[1:]);e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(1)}}
